// Prints markWordDenseMultiples switch cases for odd p in lo...hi, in PrimeSieve.swift's
// style. In a p-word group, word j's first multiple is at bit (-64 * j) mod p.
// Usage: swift word-cases.swift lo hi
let arguments = CommandLine.arguments
let lo = Int(arguments[1])!
let hi = Int(arguments[2])!
for p in stride(from: lo, through: hi, by: 2) {
    print("        case \(p):")
    print("            while word + \(p) <= fullWords {")
    for j in 0..<p {
        let first = ((-64 * j) % p + p) % p
        let target = j == 0 ? "word" : "word + \(j)"
        print("                markWord(words, \(target), first: \(first), step: \(p))")
    }
    print("                word += \(p)")
    print("            }")
}
